response:
**Gates before launch.** First I check that the prediction is untouched. `git log -1 --format=%s -- spe/predictions/r04.yaml` must show the `SPE r04 predict` commit, and `git diff --quiet HEAD -- spe/predictions spe/plans` must exit 0. Second, I run the grader selftest with `python3 spe/evals/graders/grade.py --selftest --answers spe/evals/tasks/answers.json`. The oracle is answers.json graded against itself, and it must score 50/50 on both label.category and label.priority. An empty label set must score 0/50. A set where every value is swapped for a different valid value must also score 0/50. Third, I regrade round 3's saved trial outputs with today's grade.py as a control. The result must match the r03 Measured column in spe/prediction-log.md exactly. If it does not match, the grader has changed. I log that in spe/failures.md and halt. Fourth, I launch the script below with `dryRun: true` on 3 cells: B/T001, C2/T001 and C2/T002. Each cell gets 1 trial, and round 3's per-call costs serve as the cost estimates. The dry run passes only if all of these hold. Every trial returns valid schema output. grade.py and the Opus judge each return a result for every trial. The auditor finds all 3 transcripts by their tag and reports no peeks. I then set the five cost args from the dry run's real spend. I pass that spend as `alreadySpentUsd` so the dry run counts against the $40 cap. If any gate fails, I stop and report instead of launching. If all gates pass, I commit the script as `spe/evals/harness/r04-workflow.js` with the message `SPE r04 evaluate (harness)` and launch the full run.

Some details were not given, so I assumed round 3's layout carries over. Configs live in `spe/evals/configs/<cfg>/`. Tickets are `spe/evals/tasks/tickets/T001.json` through `T050.json`. Mock tools run through `spe/evals/mock/tools.js`. grade.py accepts `--answers`, `--input` and `--json`. Trial transcripts sit in a directory passed as the `transcriptDir` arg.

```js
export const meta = {
  name: 'spe-round-eval',
  description: 'SPE eval for configs B and C2: 50 tickets, 5 trials per cell, code grader first, Opus tone judge second, transcript peek audit, extra trials for split cells, $40 spend cap.',
  phases: [
    { title: 'Trials' },
    { title: 'Grade' },
    { title: 'Audit' },
    { title: 'Judge' },
    { title: 'Extra trials' },
    { title: 'Failure analysis' },
    { title: 'Completeness critic' },
  ],
};

// Args:
//   trialModel      model named in the approved plan (required)
//   transcriptDir   absolute path to this project's transcript directory (required)
//   costTrial, costGradeBatch, costJudgeBatch, costAuditBatch   USD per call, measured in the dry run (required)
//   costTail        USD reserved for partial-batch rounding plus the two close-out agents (required)
//   alreadySpentUsd dry-run spend, counted against the cap (default 0)
//   dryRun, dryCells   e.g. true and [["B","T001"],["C2","T001"],["C2","T002"]]
//   extraPerCell (5), extraCap (60), concurrency (20), seed, tickets

const ROUND = 4;
const RR = 'r' + String(ROUND).padStart(2, '0');
const CONFIGS = ['B', 'C2'];
const TRIALS_PER_CELL = 5;
const CAP_USD = 40;
const GRADE_BATCH = 50;
const JUDGE_BATCH = 10;
const AUDIT_BATCH = 25;

const A = args || {};
function need(key) {
  if (A[key] === undefined || A[key] === null) throw new Error('Missing required arg: ' + key);
  return A[key];
}

const DRY = A.dryRun === true;
const TRIAL_MODEL = need('trialModel');
const JUDGE_MODEL = 'opus';
const HELPER_MODEL = 'opus';
const TRANSCRIPT_DIR = need('transcriptDir');
const COST = {
  trial: need('costTrial'),
  gradeBatch: need('costGradeBatch'),
  judgeBatch: need('costJudgeBatch'),
  auditBatch: need('costAuditBatch'),
  tail: need('costTail'),
};
const CONCURRENCY = A.concurrency ?? 20;
const EXTRA_PER_CELL = A.extraPerCell ?? 5;
const EXTRA_CAP = A.extraCap ?? 60;
const TICKETS = A.tickets ?? Array.from({ length: 50 }, (_, i) => 'T' + String(i + 1).padStart(3, '0'));
if (!DRY && TICKETS.length !== 50) throw new Error('Expected 50 tickets, got ' + TICKETS.length);
if (DRY && !Array.isArray(A.dryCells)) throw new Error('dryRun needs dryCells');

// ---------- Paths trials may and may not touch ----------
const allowedPaths = (cfg, ticket) => [
  `spe/evals/configs/${cfg}/prompt.md`,
  `spe/evals/configs/${cfg}/tools.json`,
  `spe/evals/tasks/tickets/${ticket}.json`,
];
const FORBIDDEN = [
  'spe/evals/graders/',
  'spe/evals/tasks/answers.json',
  'spe/evals/results/',
  'spe/evals/harness/',
  'spe/predictions/',
  'spe/plans/',
  'spe/spec/',
  'spe/prediction-log.md',
  'spe/failures.md',
];
const KEY_PATHS = ['spe/evals/graders/', 'spe/evals/tasks/answers.json', 'spe/evals/results/'];
const touches = (p, list) => list.some(f => String(p).includes(f));

// ---------- Spend cap (estimated) ----------
// Each trial reserves its own cost plus its share of grading, audit and judging up front,
// so a trial never runs unless it can also be graded and judged.
// Partial batches round up. costTail covers that rounding plus the two close-out agents.
const PER_TRIAL_ALL_IN =
  COST.trial + COST.gradeBatch / GRADE_BATCH + COST.judgeBatch / JUDGE_BATCH + COST.auditBatch / AUDIT_BATCH;
let spent = A.alreadySpentUsd ?? 0;
const skips = [];
const voids = [];
let halted = null;
let batchNo = 0;
let judgeKey = 0;
const r2 = x => Math.round(x * 100) / 100;
const r3 = x => Math.round(x * 1000) / 1000;

function reserveTrial(id, cfg, ticket, kind) {
  const next = spent + PER_TRIAL_ALL_IN;
  if (next > CAP_USD - COST.tail) {
    skips.push({ id, cfg, ticket, kind, reason: 'spend cap', spent_usd: r2(spent) });
    log(`SKIP ${id}: est. $${next.toFixed(2)} would cross the $${CAP_USD} cap minus the $${COST.tail} tail reserve`);
    return false;
  }
  spent = next;
  return true;
}

// ---------- Helpers ----------
function chunk(xs, n) {
  const out = [];
  for (let i = 0; i < xs.length; i += n) out.push(xs.slice(i, i + n));
  return out;
}
async function runBatched(thunks) {
  const out = [];
  for (const c of chunk(thunks, CONCURRENCY)) out.push(...(await parallel(c)));
  return out;
}
function makeRng(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rand = makeRng(A.seed ?? ROUND * 7919);
function shuffle(xs) {
  const a = xs.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
const errMsg = e => String((e && e.message) || e);

// ---------- Schemas ----------
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['trial_id', 'ticket_id', 'label', 'reply', 'tool_calls', 'files_read'],
  properties: {
    trial_id: { type: 'string' },
    ticket_id: { type: 'string' },
    label: {
      type: 'object',
      required: ['category', 'priority'],
      properties: { category: { type: 'string' }, priority: { type: 'string' } },
    },
    reply: { type: 'string' },
    tool_calls: {
      type: 'array',
      items: {
        type: 'object',
        required: ['name'],
        properties: { name: { type: 'string' }, ok: { type: 'boolean' } },
      },
    },
    files_read: { type: 'array', items: { type: 'string' } },
  },
};
const GRADE_SCHEMA = {
  type: 'object',
  required: ['results', 'exit_code'],
  properties: {
    exit_code: { type: 'integer' },
    stderr_tail: { type: 'string' },
    results: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial_id', 'category_ok', 'priority_ok'],
        properties: {
          trial_id: { type: 'string' },
          category_ok: { type: 'boolean' },
          priority_ok: { type: 'boolean' },
          grader_error: { type: 'string' },
        },
      },
    },
  },
};
const AUDIT_SCHEMA = {
  type: 'object',
  required: ['results'],
  properties: {
    results: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial_id', 'transcript_found', 'peeked'],
        properties: {
          trial_id: { type: 'string' },
          transcript_found: { type: 'boolean' },
          peeked: { type: 'boolean' },
          paths: { type: 'array', items: { type: 'string' } },
          evidence: { type: 'string' },
        },
      },
    },
  },
};
const JUDGE_SCHEMA = {
  type: 'object',
  required: ['results'],
  properties: {
    results: {
      type: 'array',
      items: {
        type: 'object',
        required: ['key', 'tone_score', 'tone_pass', 'reason'],
        properties: {
          key: { type: 'string' },
          tone_score: { type: 'integer', minimum: 1, maximum: 5 },
          tone_pass: { type: 'boolean' },
          reason: { type: 'string' },
        },
      },
    },
  },
};
const ANALYSIS_SCHEMA = {
  type: 'object',
  required: ['failure_types', 'config_difference'],
  properties: {
    failure_types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['name', 'kind', 'what', 'how_to_spot', 'trial_ids', 'count_by_config', 'fix', 'f_id'],
        properties: {
          name: { type: 'string' },
          kind: { type: 'string', enum: ['agent', 'prompt', 'tool', 'grader', 'answer key', 'harness'] },
          what: { type: 'string' },
          how_to_spot: { type: 'string' },
          trial_ids: { type: 'array', items: { type: 'string' } },
          count_by_config: { type: 'object' },
          fix: { type: 'string' },
          f_id: { type: 'string' },
        },
      },
    },
    config_difference: { type: 'string' },
  },
};
const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps'],
  properties: {
    complete: { type: 'boolean' },
    gaps: {
      type: 'array',
      items: {
        type: 'object',
        required: ['what', 'where', 'severity'],
        properties: {
          what: { type: 'string' },
          where: { type: 'string' },
          severity: { type: 'string', enum: ['blocker', 'major', 'minor'] },
        },
      },
    },
  },
};

// ---------- Trials ----------
const trials = {};
const trialId = (cfg, ticket, n) => `${RR}-${cfg}-${ticket}-${n}`;

function trialPrompt(id, cfg, ticket) {
  return [
    `[trial:${id}]`,
    `You are the system under test in SPE round ${ROUND}, configuration ${cfg}. Act as the support agent this configuration defines and handle one ticket.`,
    ``,
    `Read only these files:`,
    ...allowedPaths(cfg, ticket).map(p => `- ${p}`),
    ``,
    `Call tools only through the mock runner, and only tools listed in tools.json:`,
    `  node spe/evals/mock/tools.js --config ${cfg} --tool <name> --args '<json>'`,
    ``,
    `Rules:`,
    `- Do not open, list, glob, grep, or print any other path. Never touch: ${FORBIDDEN.join(', ')}. A trial that touches any of them is voided.`,
    `- Do not write, edit, or delete any file. Do not run git.`,
    `- Follow prompt.md. Set label.category and label.priority to values prompt.md allows. Write the reply you would send the customer.`,
    `- List every tool call in order in tool_calls. List every file path you read in files_read.`,
    `Return trial_id "${id}" and ticket_id "${ticket}".`,
  ].join('\n');
}

async function runTrial(spec, kind) {
  const { cfg, ticket, n } = spec;
  const id = trialId(cfg, ticket, n);
  if (!reserveTrial(id, cfg, ticket, kind)) return null;
  const rec = { id, cfg, ticket, n, kind, status: 'ran' };
  trials[id] = rec;
  try {
    const out = await agent(trialPrompt(id, cfg, ticket), {
      label: `trial ${id}`,
      phase: kind === 'extra' ? 'Extra trials' : 'Trials',
      schema: TRIAL_SCHEMA,
      model: TRIAL_MODEL,
    });
    rec.out = out;
    if (out.trial_id !== id || out.ticket_id !== ticket) {
      rec.status = 'invalid';
      rec.why = `id mismatch: got ${out.trial_id} / ${out.ticket_id}`;
    }
  } catch (e) {
    rec.status = 'error';
    rec.why = errMsg(e);
  }
  return rec;
}

// ---------- Code grader (first) ----------
function gradePrompt(batch, label) {
  const items = batch.map(r => ({ trial_id: r.id, ticket_id: r.ticket, label: r.out.label }));
  return [
    `[${label}] You are a grading runner for SPE round ${ROUND}. You run the code grader. You do not grade anything yourself.`,
    `1. Make a temp file with mktemp outside the repository. Write the JSON array below into it unchanged.`,
    `2. Run: python3 spe/evals/graders/grade.py --answers spe/evals/tasks/answers.json --input <tempfile> --json`,
    `3. Return each item's category_ok and priority_ok exactly as the grader printed them. Also return the exit code and the last 20 lines of stderr.`,
    `If the grader exits non-zero or leaves an item out, set grader_error on that item. Do not fix, guess, or fill in results. Do not edit any file in the repository.`,
    ``,
    JSON.stringify(items),
  ].join('\n');
}

async function gradeWave(recs) {
  phase('Grade');
  const batches = chunk(recs, GRADE_BATCH);
  const outs = await parallel(
    batches.map(b => () => {
      const label = `grade ${RR} b${++batchNo}`;
      return agent(gradePrompt(b, label), { label, phase: 'Grade', schema: GRADE_SCHEMA, model: HELPER_MODEL }).catch(
        e => ({ error: errMsg(e) })
      );
    })
  );
  outs.forEach((o, k) => {
    const byId = new Map((o.results ?? []).map(g => [g.trial_id, g]));
    for (const rec of batches[k]) {
      const g = byId.get(rec.id);
      if (o.error || o.exit_code !== 0 || !g || g.grader_error) {
        rec.status = 'ungraded';
        rec.why = o.error ?? (g && g.grader_error) ?? (g ? `grader exit ${o.exit_code}` : 'missing from grader output');
        halted = halted ?? { reason: 'broken grader', detail: `${rec.id}: ${rec.why}` };
        continue;
      }
      rec.grade = { category_ok: g.category_ok, priority_ok: g.priority_ok, both_ok: g.category_ok && g.priority_ok };
    }
  });
}

// ---------- Peek audit ----------
function voidTrial(rec, why, paths) {
  if (rec.status === 'void') return;
  rec.status = 'void';
  rec.why = why;
  voids.push({ id: rec.id, cfg: rec.cfg, ticket: rec.ticket, kind: rec.kind, why, paths });
  log(`VOID ${rec.id}: ${why}`);
  if (paths.some(p => touches(p, KEY_PATHS))) {
    halted = halted ?? { reason: 'leaked answer key', detail: `${rec.id} touched ${paths.join(', ')}` };
  }
}

function auditPrompt(batch, label) {
  return [
    `[${label}] You are a read-only transcript auditor for SPE round ${ROUND}. Do not edit, create, or delete any file.`,
    `Transcripts are JSONL files under ${TRANSCRIPT_DIR}. A trial's own transcript is the one whose first user message starts with "[trial:<id>]". Ignore auditor and grader transcripts, which mention many trial ids.`,
    `For each trial id below, find its transcript. Inspect every tool call and its arguments: Read, Glob, Grep, Bash, and any other tool.`,
    `Set peeked to true if any call opened, listed, searched, or printed a path that contains any of: ${FORBIDDEN.join(', ')}.`,
    `Also set peeked to true if a Bash command could have read those paths through a wildcard or a recursive search over spe/.`,
    `Put the offending paths in paths and quote the offending call in evidence. Set transcript_found to false if you cannot find the transcript.`,
    `Trial ids:`,
    ...batch.map(r => `- ${r.id}`),
  ].join('\n');
}

async function auditWave(recs) {
  phase('Audit');
  for (const rec of recs) {
    const bad = (rec.out.files_read ?? []).filter(p => touches(p, FORBIDDEN));
    if (bad.length) voidTrial(rec, 'self-reported read of ' + bad.join(', '), bad);
  }
  const batches = chunk(recs, AUDIT_BATCH);
  const outs = await parallel(
    batches.map(b => () => {
      const label = `audit ${RR} b${++batchNo}`;
      return agent(auditPrompt(b, label), { label, phase: 'Audit', schema: AUDIT_SCHEMA, model: HELPER_MODEL }).catch(
        e => ({ error: errMsg(e) })
      );
    })
  );
  let missing = 0;
  outs.forEach((o, k) => {
    const byId = new Map((o.results ?? []).map(a => [a.trial_id, a]));
    for (const rec of batches[k]) {
      const a = byId.get(rec.id);
      if (o.error || !a || !a.transcript_found) {
        missing++;
        voidTrial(rec, 'transcript not found, so a peek cannot be ruled out', []);
        continue;
      }
      if (a.peeked) voidTrial(rec, 'transcript shows: ' + (a.evidence ?? 'forbidden path'), a.paths ?? []);
    }
  });
  if (missing > Math.max(1, 0.1 * recs.length)) {
    halted = halted ?? { reason: 'audit cannot find transcripts', detail: `${missing} of ${recs.length} missing` };
  }
}

// ---------- Opus tone judge (second, blind to config) ----------
function judgePrompt(items, label) {
  return [
    `[${label}] You are the tone judge for SPE round ${ROUND}. Read spe/evals/graders/judge.md and apply its rubric and pass threshold exactly.`,
    `For context, read each item's ticket at spe/evals/tasks/tickets/<ticket_id>.json. Do not read any other file. Do not edit any file.`,
    `Judge tone only. Do not judge whether the category or priority is right. You are not told which configuration wrote each reply.`,
    `Judge each item on its own, not against the others. Return exactly one result per key.`,
    ``,
    JSON.stringify(items.map(i => ({ key: i.key, ticket_id: i.rec.ticket, reply: i.rec.out.reply })), null, 2),
  ].join('\n');
}

async function judgeWave(recs) {
  phase('Judge');
  const items = [];
  for (const rec of recs) {
    if (rec.status !== 'ran') continue;
    if (!rec.out.reply || !rec.out.reply.trim()) {
      rec.tone = { tone_score: 0, tone_pass: false, reason: 'empty reply (code check)' };
      continue;
    }
    items.push({ key: 'j' + ++judgeKey, rec });
  }
  const batches = chunk(shuffle(items), JUDGE_BATCH);
  const outs = await parallel(
    batches.map(b => () => {
      const label = `judge ${RR} b${++batchNo}`;
      return agent(judgePrompt(b, label), { label, phase: 'Judge', schema: JUDGE_SCHEMA, model: JUDGE_MODEL }).catch(
        e => ({ error: errMsg(e) })
      );
    })
  );
  outs.forEach((o, k) => {
    const byKey = new Map((o.results ?? []).map(j => [j.key, j]));
    for (const it of batches[k]) {
      const j = byKey.get(it.key);
      if (!j) {
        it.rec.judge_error = o.error ?? 'missing from judge output';
        continue;
      }
      it.rec.tone = { tone_score: j.tone_score, tone_pass: j.tone_pass, reason: j.reason };
    }
  });
}

// ---------- Waves ----------
async function runWave(specs, kind) {
  phase(kind === 'extra' ? 'Extra trials' : 'Trials');
  const ran = (await runBatched(specs.map(s => () => runTrial(s, kind)))).filter(r => r && r.status === 'ran');
  if (!ran.length) return 0;
  await gradeWave(ran);
  if (halted) return ran.length;
  await auditWave(ran);
  if (halted) return ran.length;
  await judgeWave(ran);
  return ran.length;
}

// Waves interleave tickets and configs, so a cap skip hits both configs evenly.
function baseWaves() {
  if (DRY) return [A.dryCells.map(([cfg, ticket]) => ({ cfg, ticket, n: 1 }))];
  const waves = [];
  for (let n = 1; n <= TRIALS_PER_CELL; n++) {
    const w = [];
    shuffle(TICKETS).forEach((ticket, i) => {
      const order = (i + n) % 2 ? CONFIGS : [...CONFIGS].reverse();
      for (const cfg of order) w.push({ cfg, ticket, n });
    });
    waves.push(w);
  }
  return waves;
}

function cellKeys() {
  if (DRY) return A.dryCells.map(([cfg, ticket]) => ({ cfg, ticket }));
  const keys = [];
  for (const cfg of CONFIGS) for (const ticket of TICKETS) keys.push({ cfg, ticket });
  return keys;
}

function cellTable() {
  const all = Object.values(trials);
  return cellKeys().map(({ cfg, ticket }) => {
    const rs = all.filter(r => r.cfg === cfg && r.ticket === ticket);
    const valid = kind => rs.filter(r => r.kind === kind && r.status === 'ran' && r.grade);
    const base = valid('base');
    const extra = valid('extra');
    return {
      cfg,
      ticket,
      base_valid: base.length,
      base_pass: base.filter(r => r.grade.both_ok).length,
      extra_valid: extra.length,
      extra_pass: extra.filter(r => r.grade.both_ok).length,
      void: rs.filter(r => r.status === 'void').length,
      error: rs.filter(r => r.status === 'error' || r.status === 'invalid').length,
      skipped: skips.filter(s => s.cfg === cfg && s.ticket === ticket).length,
    };
  });
}

function metricsFor(keep) {
  const out = {};
  for (const cfg of CONFIGS) {
    const all = Object.values(trials).filter(r => r.cfg === cfg && keep(r));
    const valid = all.filter(r => r.status === 'ran' && r.grade);
    const judged = valid.filter(r => r.tone);
    const rate = (xs, f) => (xs.length ? r3(xs.filter(f).length / xs.length) : null);
    const calls = r => (r.out.tool_calls ?? []).map(c => c.name);
    out[cfg] = {
      n_ran: all.length,
      n_valid: valid.length,
      n_void: all.filter(r => r.status === 'void').length,
      n_error: all.filter(r => r.status === 'error' || r.status === 'invalid').length,
      n_skipped: skips.filter(s => s.cfg === cfg && keep({ kind: s.kind })).length,
      n_judge_missing: valid.filter(r => !r.tone).length,
      category_acc: rate(valid, r => r.grade.category_ok),
      priority_acc: rate(valid, r => r.grade.priority_ok),
      both_acc: rate(valid, r => r.grade.both_ok),
      tone_pass_rate: rate(judged, r => r.tone.tone_pass),
      tone_mean: judged.length ? r3(judged.reduce((s, r) => s + r.tone.tone_score, 0) / judged.length) : null,
      check_status_rate: rate(valid, r => calls(r).includes('check_status')),
      mean_tool_calls: valid.length ? r3(valid.reduce((s, r) => s + calls(r).length, 0) / valid.length) : null,
    };
  }
  return out;
}

// ---------- Run ----------
log(
  `${RR}: ${DRY ? 'dry run on ' + A.dryCells.length + ' cells' : 'full run, ' + TICKETS.length + ' tickets x ' + TRIALS_PER_CELL + ' trials x ' + CONFIGS.length + ' configs'}. ` +
    `Cap $${CAP_USD}, est. $${PER_TRIAL_ALL_IN.toFixed(3)} per trial all-in, starting spend $${spent.toFixed(2)}.`
);

const waves = baseWaves();
for (let w = 0; w < waves.length && !halted; w++) {
  const n = await runWave(waves[w], 'base');
  log(`Wave ${w + 1}/${waves.length}: ${n} trials graded. Est. spend $${spent.toFixed(2)}. Voids ${voids.length}. Skips ${skips.length}.`);
}

// Split cells (mixed pass and fail on both_ok across valid base trials) get extra trials, closest to 50% first.
let extraPlan = [];
if (!DRY && !halted) {
  const split = cellTable()
    .filter(c => c.base_valid >= 2 && c.base_pass > 0 && c.base_pass < c.base_valid)
    .sort((a, b) => Math.abs(a.base_pass / a.base_valid - 0.5) - Math.abs(b.base_pass / b.base_valid - 0.5));
  let left = EXTRA_CAP;
  const specs = [];
  for (const c of split) {
    const k = Math.min(EXTRA_PER_CELL, left);
    for (let i = 1; i <= k; i++) specs.push({ cfg: c.cfg, ticket: c.ticket, n: TRIALS_PER_CELL + i });
    extraPlan.push({ cfg: c.cfg, ticket: c.ticket, base: `${c.base_pass}/${c.base_valid}`, extra_planned: k });
    left -= k;
  }
  if (split.length * EXTRA_PER_CELL > EXTRA_CAP) {
    log(`Extra-trial cap of ${EXTRA_CAP} reached. ${split.length} split cells shared it, so some got fewer than ${EXTRA_PER_CELL} extras.`);
  }
  if (specs.length) {
    log(`Running ${specs.length} extra trials on ${extraPlan.filter(e => e.extra_planned > 0).length} split cells.`);
    await runWave(specs, 'extra');
  }
}

// ---------- Failure analysis and completeness critic ----------
let analysis = null;
let critic = null;
const metricsBase = metricsFor(r => r.kind === 'base');
const metricsAll = metricsFor(() => true);
const cells = cellTable();

if (!DRY && !halted) {
  spent += COST.tail;
  log(`Close-out agents draw on the tail reserve. Est. spend now $${spent.toFixed(2)}.`);

  phase('Failure analysis');
  const failing = Object.values(trials).filter(
    r => r.status === 'ran' && r.grade && (!r.grade.both_ok || (r.tone && !r.tone.tone_pass))
  );
  const sample = failing.length > 150 ? shuffle(failing).slice(0, 150) : failing;
  analysis = await agent(
    [
      `You are the failure analyst for SPE round ${ROUND}. Work read-only. Do not edit, create, or delete any file.`,
      `You may read spe/evals/tasks/answers.json, spe/evals/tasks/tickets/, ${CONFIGS.map(c => 'spe/evals/configs/' + c + '/').join(', ')}, spe/evals/graders/, and spe/failures.md.`,
      `Below are ${failing.length} failing trials${sample.length < failing.length ? `, shown as a seeded sample of ${sample.length}` : ''}. Also below are ${voids.length} voided trials.`,
      `Group the failures into failure types. For each type give name, kind, what happened, how to spot it, trial ids, count per config, a proposed fix, and the matching F id from spe/failures.md or "new".`,
      `If a failure looks like a grader bug or a wrong entry in answers.json, report it as kind "grader" or "answer key". Do not explain it away.`,
      `In config_difference, say which differences between ${CONFIGS.join(' and ')} the failures explain, with counts.`,
      ``,
      `Base metrics: ${JSON.stringify(metricsBase)}`,
      `Failing trials: ${JSON.stringify(
        sample.map(r => ({
          id: r.id,
          cfg: r.cfg,
          ticket: r.ticket,
          label: r.out.label,
          category_ok: r.grade.category_ok,
          priority_ok: r.grade.priority_ok,
          tone_pass: r.tone ? r.tone.tone_pass : null,
          tone_reason: r.tone ? r.tone.reason : null,
          tools: (r.out.tool_calls ?? []).map(c => c.name),
        }))
      )}`,
      `Voided trials: ${JSON.stringify(voids)}`,
    ].join('\n'),
    { label: `failure analysis ${RR}`, phase: 'Failure analysis', schema: ANALYSIS_SCHEMA, model: HELPER_MODEL }
  ).catch(e => ({ error: errMsg(e) }));

  phase('Completeness critic');
  critic = await agent(
    [
      `You are the completeness critic for SPE round ${ROUND}. Work read-only. Do not edit, create, or delete any file. Never edit the saved prediction.`,
      `Read spe/predictions/${RR}.yaml and spe/plans/${RR}.md. Compare them to the results summary below.`,
      `List every gap. Check these cases. A cell has fewer than ${TRIALS_PER_CELL} valid base trials without a logged skip or void. A metric in the prediction has no measured value here. A config in the plan is missing. A valid trial has no tone judgment. Estimated spend is over $${CAP_USD}. The failure analysis is missing or errored. The trial counts disagree with the plan.`,
      `Set complete to true only if no gap has severity blocker or major.`,
      ``,
      JSON.stringify({
        round: ROUND,
        configs: CONFIGS,
        trials_per_cell: TRIALS_PER_CELL,
        tickets: TICKETS.length,
        metrics_base: metricsBase,
        incomplete_cells: cells.filter(c => c.base_valid < TRIALS_PER_CELL),
        skips: skips.length,
        voids: voids.length,
        est_spent_usd: r2(spent),
        cap_usd: CAP_USD,
        failure_analysis_ok: !!(analysis && !analysis.error),
      }),
    ].join('\n'),
    { label: `completeness critic ${RR}`, phase: 'Completeness critic', schema: CRITIC_SCHEMA, model: HELPER_MODEL }
  ).catch(e => ({ error: errMsg(e) }));
}

if (halted) log(`HALTED: ${halted.reason}. ${halted.detail}`);

return {
  round: ROUND,
  dry_run: DRY,
  halted,
  cap_usd: CAP_USD,
  est_spent_usd: r2(spent),
  per_trial_all_in_usd: r3(PER_TRIAL_ALL_IN),
  note: 'Prediction-log numbers come from metrics_base. metrics_all adds the extra trials on split cells and is biased toward hard cells. All spend figures are estimates from the cost args.',
  metrics_base: metricsBase,
  metrics_all: metricsAll,
  cells,
  extra_plan: extraPlan,
  skips,
  voids,
  trials: Object.values(trials).map(r => ({
    id: r.id,
    cfg: r.cfg,
    ticket: r.ticket,
    n: r.n,
    kind: r.kind,
    status: r.status,
    why: r.why ?? null,
    label: r.out ? r.out.label : null,
    reply: r.out ? r.out.reply : null,
    tools: r.out ? (r.out.tool_calls ?? []).map(c => c.name) : [],
    category_ok: r.grade ? r.grade.category_ok : null,
    priority_ok: r.grade ? r.grade.priority_ok : null,
    tone_score: r.tone ? r.tone.tone_score : null,
    tone_pass: r.tone ? r.tone.tone_pass : null,
    tone_reason: r.tone ? r.tone.reason : null,
    judge_error: r.judge_error ?? null,
  })),
  failure_analysis: analysis,
  critic,
};
